#!/usr/bin/env python3
"""Regenerate the large synthetic fixture pattern (invented names only).

Usage: python3 make_large.py [OUTPUT_DIR]

Writes OUTPUT_DIR/large-pattern.yaml (default: the catalog folder next to this
script). Output depends only on the seed below: no timestamps, no paths, no
environment values, and every ordering is by index or uid. Run it twice and
the bytes are identical.
"""
from __future__ import annotations

import random
import sys
from pathlib import Path
from typing import Any

import yaml

SEED = 7
SDP_UID = "FXSDP00003-0001"
TARGETS = ["fx-cloud-east", "fx-cloud-west", "fx-dc-north"]
ZONES = ["fx-public", "fx-app", "fx-data"]
ZONE_TIERS = {"fx-public": "frontend", "fx-app": "application", "fx-data": "data"}
GROUP_COUNT = 12
OBJECTS_PER_GROUP = 5
RELATIONSHIP_COUNT = 100
TIERS = ["presentation", "application", "data", "utility"]
KINDS = ["product_component"] * 3 + ["data_component", "data_store_service"]
LABELS = ["calls", "reads", "writes", "publishes", "subscribes to", "queries", "notifies", "syncs with"]
DIRECTIONS = ["synchronous", "asynchronous", "event", None]
FLOWS = ["outbound", "inbound", "bidirectional", None]


def uid_for(prefix: str, index: int) -> str:
    return f"FX{prefix}{index:05d}-0001"


def build(rng: random.Random) -> list[dict[str, Any]]:
    docs: list[dict[str, Any]] = []
    runtimes = [uid_for("GRT", i + 1) for i in range(GROUP_COUNT)]
    runtime_docs = [
        {
            "schemaVersion": "1.0",
            "uid": uid,
            "type": "runtime_service",
            "name": f"FX Large Runtime {i + 1:02d}",
            "productName": "FX Large Orchestrator",
            "catalogStatus": "complete",
            "lifecycleStatus": "preferred",
        }
        for i, uid in enumerate(runtimes)
    ]
    object_uids: list[str] = []
    object_docs: list[dict[str, Any]] = []
    groups: list[dict[str, Any]] = []
    index = 0
    for g in range(GROUP_COUNT):
        deployable = []
        for _ in range(OBJECTS_PER_GROUP):
            index += 1
            kind = KINDS[(index - 1) % len(KINDS)]
            uid = uid_for("GPR", index)
            obj: dict[str, Any] = {
                "schemaVersion": "1.0",
                "uid": uid,
                "type": kind,
                "name": f"FX Large Part {index:03d}",
                "catalogStatus": "complete",
                "lifecycleStatus": "preferred",
            }
            if kind == "product_component":
                obj["language"] = ["Go", "Java", "Python", "TypeScript"][rng.randrange(4)]
                obj["runsOn"] = runtimes[g] if rng.random() < 0.8 else runtimes[rng.randrange(GROUP_COUNT)]
            elif kind == "data_component":
                obj["targetEngine"] = "FX KeyValue"
            else:
                obj["productName"] = "FX Large Store"
            object_uids.append(uid)
            object_docs.append(obj)
            entry: dict[str, Any] = {"ref": uid, "networkZone": ZONES[rng.randrange(len(ZONES))]}
            if rng.random() < 0.9:
                entry["diagramTier"] = TIERS[rng.randrange(len(TIERS))]
            deployable.append(entry)
        groups.append(
            {
                "name": f"Large Group {g + 1:02d}",
                "deploymentTarget": TARGETS[g % len(TARGETS)],
                "substrate": runtimes[g],
                "deployableObjects": deployable,
            }
        )
    relationships: list[dict[str, Any]] = []
    for r in range(RELATIONSHIP_COUNT):
        source = object_uids[rng.randrange(len(object_uids))]
        target = object_uids[rng.randrange(len(object_uids))]
        rel: dict[str, Any] = {
            "schemaVersion": "1.0",
            "uid": uid_for("KED", r + 1),
            "type": "relationship",
            "name": f"FX Large Edge {r + 1:03d}",
            "source": source,
            "target": target,
            "label": LABELS[rng.randrange(len(LABELS))],
            "catalogStatus": "complete",
        }
        direction = DIRECTIONS[rng.randrange(len(DIRECTIONS))]
        if direction is not None:
            rel["direction"] = direction
        flow = FLOWS[rng.randrange(len(FLOWS))]
        if flow is not None:
            rel["flow"] = flow
        relationships.append(rel)
    sdp = {
        "schemaVersion": "1.0",
        "uid": SDP_UID,
        "type": "software_deployment_pattern",
        "name": "FX Large Synthetic Pattern",
        "description": "Generated by make_large.py from a fixed seed. Invented names; do not edit by hand.",
        "owner": {"team": "fx-team-large"},
        "catalogStatus": "complete",
        "lifecycleStatus": "candidate",
        "networkZones": [{"id": z, "name": z.replace("fx-", "FX ").title(), "tier": ZONE_TIERS[z]} for z in ZONES],
        "serviceGroups": groups,
    }
    docs.append(sdp)
    docs.extend(runtime_docs)
    docs.extend(object_docs)
    docs.extend(relationships)
    return docs


def main(argv: list[str]) -> int:
    out_dir = Path(argv[1]) if len(argv) > 1 else Path(__file__).resolve().parent / "catalog"
    out_dir.mkdir(parents=True, exist_ok=True)
    docs = build(random.Random(SEED))
    text = "# Generated by tests/fixtures/diagram_workspace/make_large.py (seed 7). Do not edit by hand.\n"
    text += yaml.safe_dump_all(docs, sort_keys=False, allow_unicode=True, width=100)
    (out_dir / "large-pattern.yaml").write_text(text, encoding="utf-8", newline="\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
